/** הצהרות טיפוס לנכסי תמונה המיובאים כ-URL ע"י Vite. */
declare module '*.avif' {
  const src: string;
  export default src;
}
declare module '*.webp' {
  const src: string;
  export default src;
}
declare module '*.png' {
  const src: string;
  export default src;
}
declare module '*.jpg' {
  const src: string;
  export default src;
}
